// Function to simulate physics: Current moves toward Target
function simulateRoom(roomId, defaultTarget) {
    var target = flow.get('temp_target_' + roomId) || defaultTarget;
    var current = flow.get('temp_current_' + roomId) || 20.0;

    var diff = target - current;
    if (Math.abs(diff) > 0.05) {
        current += (diff > 0 ? 0.1 : -0.1);
    }

    // Add realistic jitter
    current += (Math.random() - 0.5) * 0.04;

    flow.set('temp_current_' + roomId, current);
    return parseFloat(current.toFixed(2));
}

